dict(
  ver='0.101h', key='research1021', at='2026-10-21T09:16:00Z', name='Research Round', pill='Harry branch &middot; research',
  card='Five research pieces, no game change: headers and volleys, navigation, what Leo\'s and Mikey\'s work reaches, the simulation rebuild plan, and build-ups measured.',
  eyebrow='RESEARCH · NO GAME CHANGE', h1='Five questions answered with numbers, ready for Harry to pick from.',
  status='Research only. Nothing in the game changed.', sub='21 Oct 2026, 00:34 to 04:44. Full write-ups in docs/research/ and docs/plans/.',
  summary='Research, 21 Oct. (1) Headers and volleys: headers are about 18 goals in 100, volleys 23; the real-highlights data already holds about 67 header-height and 102 volley-height shots the game never serves. (2) Navigation: keep the five-button bar; fix Back, one back button, the house icon, the bar on more screens, a cleaner Phone, doors for Transfers and Career. (3) Leo/Mikey audit: the 4,393 league goals reach only the Real Goals page; StatsBomb-derived numbers are still in the code. (4) Simulation plan: the live game still runs the Old unseen match (15.2 shots, no corners, 15% scored; real 23.6, 9.9, 10.4%); free Wyscout data replaces StatsBomb almost one for one. (5) Build-ups measured: +33 s a match On (111 → 144 s), 7% end offside with no chance, a 3D build-up stretches below 20 fps.',
  stats=[('18 / 23', 'goals in 100 that are headers / volleys (real)'), ('+33 s', 'per match with build-ups On (111 → 144 s)'), ('15.2 vs 23.6', 'shots a match: live game vs real football'), ('0 of 4,393', 'league goals that reach a highlight today')],
  check=[('Read the five summaries', 'Each has a plain-English summary at the top and options to pick from.')],
  sections=[
    dict(kind='added', title='What we found', items=[
      dict(h='Headers, volleys and acrobatics', tags=['meas'],
           problem='Harry: &ldquo;make it a really great feature … linked to a certain skill&rdquo;.',
           fix='Real numbers (34,853 shots, 1,401 matches): headers 16 shots and 18 goals in 100; volleys 21 and 23; bicycle kicks 6 shots in 1,000 (one goal in about 108 matches); diving headers 4 in 1,000 but 20% score. From 6 to 11 m: foot 29%, volley 20%, header 9.5%. A defender on a header inside 16 m: 7.6% against 13.7% free. Biggest find: the real-highlights data already has about 67 header-height and 102 volley-height shots that the game never serves.',
           more=('Where', ['docs/research/2026-10-21-headers-volleys-acrobatics.md'])),
      dict(h='Navigation', tags=['seen', 'reas'],
           problem='Harry: &ldquo;what\'s the optimal idea for the flow and place of everything&rdquo;.',
           why='Today: Back sends you Home from Ownership, Sponsors, Casino, Trophies and Achievements; 8 different back buttons; about 40 screens lose the bottom bar; the Phone holds 14 apps, 3 of them copies; Transfers and Career have no door.',
           fix='Recommended: keep the five buttons and the big Play, and apply four rules everywhere: Back returns where you came from; places keep the bar, scenes take the phone; the house always means Home; anything that needs you shows a dot. 13 of 15 places are already one or two taps from Home.',
           figs=[(r('2026-10-21-navigation', 'home.png'), 'Home today.', 'ph'), (r('2026-10-21-navigation', 'phone.png'), 'The Phone: 14 apps.', 'ph')],
           more=('Where', ['docs/research/2026-10-21-navigation.md'])),
      dict(h='What Leo\'s and Mikey\'s work reaches', tags=['meas'],
           problem='Is the work on main wired into Harry\'s systems?',
           fix='Leo\'s 4,393 league goals reach the Real Goals page only: 0 can be served as highlights (one line excludes Wyscout), and none reach the radar or the simulation. 2,166 of them would fit the highlights. Mikey\'s pages are in the admin with eyes. Not asked, but found: several live numbers were tuned from StatsBomb data, which was deleted on 19 Oct for its licence; the numbers stayed.',
           more=('Where', ['docs/research/2026-10-21-leo-mikey-integration.md'])),
      dict(h='The simulation rebuild plan', tags=['meas', 'reas'],
           problem='Harry: use the new highlights system and the 4,400 matches to massively improve the simulation and the radar, with licensed data only.',
           why='The live game still runs the Old unseen match (Settings Match flow defaults to Old).',
           fix='Plan, not built. Free Wyscout and tracking data match StatsBomb\'s three biggest numbers almost exactly (striker on the ball 47/36/17% vs 49/31/20%; back line 0.66 vs 0.66; keeper saves 46/73/90% vs 53/77/90%). Order: get the data, then shots and corners, then fouls, cards and offsides, then roles, then make the radar the match.',
           bars=[('Shots a match: live game (Old)', 23.6, 15.2, 'real 23.6', '15.2', 'warn'), ('Corners a match: live game', 9.9, 0, 'real 9.9', '0', 'bad'), ('Share of shots scored, live (%)', 10.4, 15.2, 'real 10.4', '15.2', 'warn')],
           more=('Where', ['docs/plans/2026-10-21-sim-formula-rebuild.md'])),
      dict(h='Build-ups measured', tags=['meas', 'seen'],
           problem='Harry: Off feels snappy; is On too slow, and does the camera work?',
           fix='On, 92% of chances get a build-up, 6.4 s on average: 111 → 144 s a match (+33 s, +30%; a real player\'s share is more like +15 to 25%). 7% of build-ups end in a called offside with no chance. The ball is off the glass in 1.1%; the real issue is framing (in 55% of build-ups a passer or receiver is off screen for over 0.3 s). In 3D the build-up plays, but below 20 fps it runs in slow motion. Options: play only the last 3 s (saves 18 s a match), a calmer camera, and three 3D choices.',
           bars=[('Seconds a match in chances (Off → On)', 111, 144, '111', '144', 'warn')],
           figs=[(r('2026-10-21-buildups', 'game-buildup-start-empty-bottom.jpg'), 'A real build-up start: lots of empty grass.', 'ph'), (r('2026-10-21-buildups', '3d-buildup-late.jpg'), 'The build-up playing in 3D.', 'ph')],
           more=('Where', ['docs/research/2026-10-21-buildups-measured.md'])),
    ]),
  ],
  seen=dict(seen=['Navigation: 8 screens at 390×844', 'Build-ups: real game stills and a 3D run'], meas=['Headers/volleys from 34,853 real shots', 'Build-up times over 5 career matches and 582 generated build-ups', 'Simulation: 1,000 matches per strength pair'],
            reas=['The recommendations in each piece', 'Phone frame rates in 3D (reasoned from this machine)']),
  footer='21 Oct 2026. Research only: no game code changed.'),

